        hh=max(p[0] for p in comp)-r0+1; ww=max(p[1] for p in comp)-c0+1
        # target: what O puts there (ground truth for validation); for solving use: keep 6 cells free, need pattern == O-subgrid where O!=6, src 6-free
        tpat=[[O[r0+i][c0+j] if O[r0+i][c0+j]!=6 else 6 for j in range(ww)] for i in range(hh)]
