        for nm in tforder:
            tr=np.array(DIH[nm](I)); th,tw=tr.shape
            for rr in range(th-hh+1):
                for cc in range(tw-ww+1):
                    # candidate window in view must have no 6 AND match tpat on non-6 cells
                    good=True
                    for i in range(hh):
                        for j in range(ww):
                            v=int(tr[rr+i,cc+j])
                            if v==6 or (tpat[i][j]!=6 and v!=tpat[i][j]): good=False;break
                        if not good: break
                    if not good: continue
                    dd=min(abs(rr+i-a)+abs(cc+j-b) for a,b in hc for i in range(hh) for j in range(ww))
                    cands.append((dd,nm,rr,cc))
        if not cands: print(pair,'NO CAND'); continue
        d_,nm,rr,cc=min(cands)
        for i in range(hh):
            for j in range(ww):
                out[r0+i][c0+j]=int(DIH[nm](I)[rr+i,cc+j])
        tot+=1
