import numpy as np, os, re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
TF=['id','lr','ud','r180','T','lrT','udT','lr180']
D={'id':lambda g:g,'lr':lambda g:g[:,::-1],'ud':lambda g:g[::-1,:],'r180':lambda g:g[::-1,::-1],
   'T':lambda g:g.T,'lrT':lambda g:g.T[:,::-1],'udT':lambda g:g.T[::-1,:],'lr180':lambda g:g.T[::-1,::-1]}
def mappt(nm,x,y,H,W):
    if nm=='id':return x,y
    if nm=='lr':return x,W-1-y
    if nm=='ud':return H-1-x,y
    if nm=='r180':return H-1-x,W-1-y
    if nm=='T':return y,x
    if nm=='lrT':return y,W-1-x
    if nm=='udT':return H-1-y,x
    return H-1-y,W-1-x
def ccs6(Ig):
    I=np.array(Ig); seen=np.zeros_like(I,bool); out=[]
    for a in range(I.shape[0]):
        for b in range(I.shape[1]):
            if I[a,b]==6 and not seen[a,b]:
                st=[(a,b)]; comp=[]
                while st:
                    y,x=st.pop()
                    if 0<=y<I.shape[0] and 0<=x<I.shape[1] and I[y,x]==6 and not seen[y,x]:
                        seen[y,x]=True; comp.append((int(y),int(x)))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)): st.append((y+dy,x+dx))
                out.append(comp)
    return out
def f(Ig):
    I=np.array(Ig); H,W=I.shape; out=I.copy()
    for cc in ccs6(Ig):
        rs=[p[0] for p in cc]; cs=[p[1] for p in cc]
        r0=min(rs);c0=min(cs);hh=max(rs)-r0+1;ww=max(cs)-c0+1
        # we don't know the target pattern without O -> can't verify; but rule: fill each 6-comp with nearest same-shape 6-free window (dihedral views) mapped to original coords
        cands=[]
        for nm in TF:
            tr=D[nm](I)
            th,tw=tr.shape
            for i in range(th-hh+1):
                for j in range(tw-ww+1):
                    s=tr[i:i+hh,j:j+ww]
                    if (s!=6).all():
                        oi,oj=mappt(nm,i,j,H,W)
                        dnn=min(abs(mappt(nm,i+a,j+b)[0]-pa)+abs(mappt(nm,i+a,j+b)[1]-pb) for pa,pb in cc for a in range(hh) for b in range(ww))
                        cands.append((dnn,nm,i,j))
